import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dataDir = path.join(__dirname, 'data');

function errorResult(message) {
  return {
    isError: true,
    content: [{ type: 'text', text: message }]
  };
}

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Relative path of the file within the data directory.' }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (!args || typeof args !== 'object' || Array.isArray(args)) {
    return errorResult('Arguments must be an object.');
  }
  const { path: inputPath } = args;
  if (typeof inputPath !== 'string' || inputPath.length === 0) {
    return errorResult('path is required and must be a non-empty string.');
  }
  // Reject absolute paths
  if (path.isAbsolute(inputPath)) {
    return errorResult('path must be relative to the data directory.');
  }
  const resolved = path.resolve(dataDir, inputPath);
  const rel = path.relative(dataDir, resolved);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    return errorResult('path must stay within the data directory.');
  }
  // Check exists and is file
  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (e) {
    return errorResult('File not found.');
  }
  if (!stat.isFile()) {
    return errorResult('path must point to a file.');
  }
  const ext = path.extname(resolved).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size}\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
